st=[]
page(st,'09 / SERVIÇO OPCIONAL','Assistente de Recepção Digital',[('Clínica Odonto Personnallite',['Projeto de atendimento inicial pelo WhatsApp para orientar interessados e organizar solicitações para a recepção. Complemento opcional à proposta de divulgação local, com contratação e custos próprios.','Primeira versão com menu e respostas aprovadas. Inteligência artificial, agenda integrada e lembretes não fazem parte da versão inicial.']),('Situação atual',['A demonstração interativa está publicada e utiliza respostas fixas, sem conexão com o WhatsApp. Não envia mensagens, não guarda dados e não cria agendamentos.','Veja: https://clinica-sorriso.mandre-soeiro.workers.dev/demonstracao-assistente','A solução real depende de plataforma oficial compatível, conta da clínica, acessos e aprovação comercial. Nada está sendo contratado ou ativado por este documento.'])])
st.append(table([('Referência comercial para fluxo simples','Valor'),('Implantação em plataforma pronta compatível','R$ 600 únicos'),('Manutenção com escopo limitado','R$ 150/mês'),('Plataforma, mensagens e demais terceiros','Sob cotação separada')]))
st.extend([Spacer(1,12),p('Condição preliminar, não um orçamento fechado. Confirmar a viabilidade técnica e o custo da plataforma antes do aceite. Desenvolver painel próprio, agenda ou IA exige nova proposta.','Small')])
page(st,'FLUXO DE ATENDIMENTO','Do interesse à recepção',[('Jornada proposta',['Anúncio ou Instagram > landing page > WhatsApp > assistente > recepção > confirmação da consulta pela equipe.','O assistente organiza o primeiro contato. Não realiza avaliação odontológica, não confirma disponibilidade sem integração e não garante agendamentos.']),('Menu e respostas',['Boas-vindas: Olá! Sou o assistente virtual da Clínica Odonto Personnallite. Como posso ajudar?','1. Solicitar agendamento: pedir nome e preferência de período. Confirmar apenas o recebimento da solicitação; encaminhar à recepção. Não reservar horário.','2. Tratamentos: apresentar até três respostas curtas aprovadas pela responsável técnica e oferecer contato humano. Não indicar tratamento personalizado ou informar diagnóstico.','3. Endereço e horários: apresentar dados oficiais validados e explicar como falar com a equipe.','4. Recepção: encaminhar à fila humana, pausar a automação e informar o horário de atendimento validado. Não prometer resposta imediata.']),('Exemplo de conclusão',['Obrigado, Maria! Recebemos sua preferência pelo período da tarde. A recepção verificará a disponibilidade e confirmará o horário. Esta solicitação ainda não é um agendamento confirmado.']),('Exceções',['Mensagem não reconhecida: reapresentar o menu e oferecer a recepção. Pedido clínico ou relato de urgência: encaminhar à equipe com texto previamente aprovado, sem triagem automática ou diagnóstico.','Fora do horário: informar os horários reais e encaminhar à fila, sem prometer atendimento ou monitoramento em tempo real.'])])
page(st,'IMPLEMENTAÇÃO','O que será construído',[('Escopo da primeira versão',['Um número da clínica e um menu principal com até quatro caminhos. Até três respostas fixas sobre tratamentos, além de localização e horários.','Fluxo de solicitação com nome e preferência de período; mensagem de conclusão e encaminhamento humano.','Configuração da caixa de atendimento já oferecida pela plataforma escolhida. Registro com estados básicos, quando suportados: novo contato, aguardando recepção e atendido.','Regra para interromper o robô durante atendimento humano e retomada controlada conforme os recursos da plataforma.','Uma rodada consolidada de revisão do fluxo e uma orientação remota à recepção de até uma hora.']),('Arquitetura proposta',['Integração oficial do WhatsApp + plataforma com caixa humana + automação configurada pelo prestador. A conta e o número pertencem à clínica.','A escolha técnica considera custo total, atendimento humano, permissões, histórico, exportação e condições de uso do número atual. Não migrar o número sem validar o impacto e combinar a mudança.','Se for necessário backend próprio, hospedagem ou banco de dados, apresentar orçamento adicional antes de desenvolver. A primeira versão não inclui construção de uma caixa de atendimento do zero.']),('Fora deste escopo',['IA generativa, áudio, agenda automática, confirmação ou cancelamento automático, CRM externo, pagamentos, lembretes ativos, campanhas de mensagens, prontuários, painel próprio e atendimento humano realizado pelo prestador.'])])
page(st,'RESPONSABILIDADES','Quem executa cada parte',[('Prestador',['Mapear o fluxo com a clínica, avaliar a plataforma e apresentar custos antes da contratação.','Configurar as integrações e respostas aprovadas, testar as situações previstas, documentar a operação e orientar a recepção.','Manter credenciais no ambiente apropriado, sem expor chaves no site ou nos documentos.','Na manutenção contratada, conferir a operação e executar pequenos ajustes dentro do limite; comunicar falhas identificadas.']),('Clínica',['Validar respostas, serviços, registros profissionais, horários e regras de atendimento; fornecer materiais autorizados.','Contratar e pagar fornecedores em seu nome, disponibilizar acessos por convite quando possível e manter recuperação e autenticação em duas etapas.','Designar quem atende a fila, conferir disponibilidade, confirmar consultas e atualizar o estado dos contatos.','Aprovar a política de acesso, retenção e exclusão dos dados conforme a operação e as obrigações aplicáveis.']),('Dados e atendimento',['Coletar apenas o necessário ao pedido. Não solicitar CPF, exames, histórico de saúde ou fotos clínicas no fluxo inicial.','Restringir o acesso às pessoas autorizadas. Definir e documentar retenção, exportação e exclusão antes da ativação; verificar as condições dos fornecedores.','Relatórios devem priorizar totais agregados. Não expor conteúdo clínico ou dados identificáveis em apresentações comerciais.','O assistente não é um canal clínico de emergência. A clínica deve aprovar como orientar pedidos urgentes e explicar seus horários de monitoramento.'])])
page(st,'FINANCEIRO','Seu serviço e os fornecedores',[('Implantação preliminar - R$ 600',['Pagamento sugerido: 2 parcelas de R$ 300, após validação técnica e aceite. Primeira no início; segunda na aprovação dos testes antes da ativação.','Distribuição para apresentação: desenho e validação do fluxo R$ 150; configuração da plataforma e integração R$ 250; testes e ajustes R$ 100; documentação e orientação R$ 100.','Essa referência cobre configuração em plataforma pronta compatível. Se os requisitos não couberem nesse escopo, emitir novo orçamento, sem cobrança adicional automática.']),('Manutenção preliminar - R$ 150/mês',['Até uma hora mensal não acumulativa para conferências e pequenos ajustes de respostas, horários ou encaminhamentos. Mensalidade a partir da ativação acordada.','Não inclui suporte 24 horas, atendimento aos pacientes, novas integrações, mudanças extensas de fluxo ou custos dos fornecedores. Canal e horário de suporte serão definidos no aceite.']),('Terceiros pagos pela clínica',['Plataforma e caixa de atendimento: preço a cotar, incluindo quantidade de usuários e limites.','Mensagens da integração oficial: conforme categorias, uso, tarifas e condições vigentes do fornecedor. Não prometer consumo ilimitado.','Hospedagem e armazenamento: apenas se necessários e aprovados. IA da OpenAI: fora da primeira versão; uso e cobrança próprios em eventual evolução.','Não confundir esses valores com os R$ 300 de anúncios da Meta. Verba de publicidade e custos do atendimento WhatsApp são despesas diferentes.']),('Exemplo junto à divulgação local',['Serviços atuais: R$ 500/mês. Manutenção do assistente: +R$ 150/mês. Total de serviços: R$ 650/mês.','Com R$ 300/mês de anúncios: R$ 950/mês, MAIS plataforma e mensagens ainda a cotar. Não é um total final fechado.','Implantação atual R$ 900 + assistente preliminar R$ 600 = R$ 1.500 em pagamentos únicos, com calendários separados. Kit opcional e domínios permanecem fora.'])])
page(st,'TESTES E ENTREGA','Antes de colocar em funcionamento',[('Etapas e prazo estimado',['1. Validar a demonstração com a dona e a recepção. Confirmar menu, respostas e responsabilidades.','2. Cotar e escolher a plataforma, validar a conta e o uso do número. Aprovar o orçamento final antes da contratação.','3. Configurar o fluxo e a caixa humana em ambiente de testes.','4. Executar os testes e orientar a equipe. Registrar aceite e data de ativação.','5. Ativar e acompanhar dentro da manutenção contratada. Prazo inicial estimado: 7 a 15 dias úteis após todos os acessos e aprovações; verificações externas podem alterar esse prazo.']),('Critérios de aceite',['Menu e todos os caminhos funcionam; escolhas inválidas oferecem retorno e atendimento humano.','A solicitação contém apenas os dados combinados e não é apresentada como consulta confirmada.','Encaminhamento cria acesso efetivo à recepção; bot pausa durante a conversa humana. A equipe consegue responder e encerrar.','Mensagens fora do horário são claras; falhas e indisponibilidade têm orientação de atendimento definida.','Repetições e reenvios não devem criar solicitações duplicadas; conferir os recursos da plataforma.','Acesso da equipe, permissões e instruções de operação são conferidos antes de usar dados reais.']),('Indicadores de acompanhamento',['Quantidade de conversas iniciadas, solicitações, encaminhamentos e falhas identificadas. A clínica informa agendamentos confirmados e comparecimentos em totais agregados.','Uso e despesas dos fornecedores revisados separadamente. Resultados não são garantia de vendas ou retorno financeiro.']),('Evolução opcional',['Depois de validar o fluxo: avaliar IA com conteúdo aprovado, agenda ou lembretes, um recurso por vez. Cada evolução depende de viabilidade, regras de uso, dados necessários e orçamento separado.'])])
page(st,'APROVAÇÃO','Decisão e próximos passos',[('Condições',['Documento preliminar emitido em 12/10/2026 para discutir o projeto. Referências de honorários válidas por 15 dias; nenhum custo externo foi cotado ou contratado.','Antes de aceitar, anexar plataforma escolhida, custos, acesso ao número, datas, política de suporte e forma de contratação do prestador (CPF ou CNPJ e documentação aplicável).','Mensalidade antecipada; continuidade e encerramento com aviso de 30 dias propostos, sujeitos ao contrato final. Parcelas de trabalho de implantação já contratado permanecem devidas.','A conta, o número e os dados da clínica continuam sob sua titularidade; credenciais e configurações serão documentadas. Eventual transferência segue os recursos e condições do fornecedor.']),('Quadro para fechar a contratação',['Plataforma: _____________________  Valor: R$ ______/mês  Usuários: ______','Mensagens: regra/tarifa ______________________________________________','Outros custos aprovados: ____________________________________________','Implantação final: R$ ______  Manutenção: R$ ______/mês','Responsável da recepção: ______________  Horário de suporte: __________','Prestador / CPF ou CNPJ: _____________________________________________','Clínica / responsável: ______________________________________________','Aceite: __________________________  Data: __________________________'])])
